export const W=960,H=540;
export const weapons={shell:{name:'Granat',radius:44,damage:54,cost:0},heavy:{name:'Tung granat',radius:68,damage:72,cost:250},cluster:{name:'Klynge',radius:52,damage:42,cost:400}};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function terrain(seed){let s=seed>>>0;const random=()=>((s=(Math.imul(s,1664525)+1013904223)>>>0)/4294967296);const phase=random()*6.28;return Array.from({length:W},(_,x)=>Math.round(391+34*Math.sin(x/96+phase)+22*Math.sin(x/41+phase*1.7)+12*Math.sin(x/19+phase*.7)));}
export function newGame({seed=Math.floor(Math.random()*2**32),mode='standard',names=['Du','Computer']}={}){const ground=terrain(seed);return {seed,mode,ground,wind:Math.round(((seed%19)-9)*.8),turn:0,round:1,maxRounds:5,shots:0,players:[{name:names[0],x:105,yBefore:ground[105],hp:100,cash:500,score:0,kills:0,angle:48,power:66},{name:names[1],x:855,yBefore:ground[855],hp:100,cash:500,score:0,kills:0,angle:48,power:66}],last:null,winner:null};}
export function trace(state,player,angle,power){const p=state.players[player],dir=player? -1:1,r=angle*Math.PI/180,speed=power*5.2;let x=p.x+dir*18*Math.cos(r),y=state.ground[p.x]-17-18*Math.sin(r),vx=dir*speed*Math.cos(r),vy=-speed*Math.sin(r);const path=[];for(let i=0;i<1100;i++){x+=vx/60;y+=vy/60;vx+=state.wind*.85/60;vy+=255/60;if(i%3===0)path.push([x,y]);if(x<0||x>=W||y>H+80)return {x:clamp(x,0,W-1),y:clamp(y,0,H),path,miss:true};if(y>=state.ground[Math.floor(x)])return {x,y:state.ground[Math.floor(x)],path,miss:false};}return {x,y,path,miss:true};}
function scoreDamage(state,shooter,damage){if(state.mode==='standard'||state.mode==='greedy')state.players[shooter].score+=damage*10;}
export function fire(state,{angle,power,weapon='shell'}={}){if(state.winner!==null)throw Error('Kampen er slut');if(!Number.isInteger(angle)||angle<5||angle>85||!Number.isInteger(power)||power<10||power>100||!weapons[weapon])throw Error('Ugyldigt skud');const actor=state.turn,p=state.players[actor],w=weapons[weapon];if(p.cash<w.cost)throw Error('Ikke nok kredit');p.cash-=w.cost;p.angle=angle;p.power=power;const hit=trace(state,actor,angle,power);const blasts=[[hit.x,hit.y,w.radius,w.damage]];if(weapon==='cluster'&&!hit.miss)blasts.push([hit.x-36,hit.y,28,24],[hit.x+36,hit.y,28,24]);const damages=[0,0];for(const [x,y,r,d] of blasts){if(hit.miss)continue;for(let i=Math.max(0,Math.floor(x-r));i<Math.min(W,Math.ceil(x+r));i++){const depth=Math.sqrt(Math.max(0,r*r-(i-x)**2));state.ground[i]=Math.min(H-16,Math.max(state.ground[i],Math.round(y+depth*.72)));}for(let i=0;i<2;i++){const target=state.players[i];const distance=Math.hypot(target.x-x,state.ground[target.x]-12-y);const amount=Math.round(d*clamp(1-distance/(r+16),0,1));const actual=Math.min(target.hp,amount);target.hp-=actual;damages[i]+=actual;if(i!==actor){scoreDamage(state,actor,actual);state.players[actor].cash+=actual*5;}}}
for(const target of state.players){const drop=state.ground[target.x]-(target.yBefore??state.ground[target.x]);target.yBefore=state.ground[target.x];if(drop>28)target.hp=Math.max(0,target.hp-Math.round((drop-28)/3));}
let ended=state.players.some(q=>q.hp<=0)||state.shots>=39;state.shots++;if(ended){const alive=state.players.map(q=>q.hp>0);if(alive[actor]&&!alive[1-actor]){p.kills++;p.score+=state.mode==='basic'?1000:500;p.cash+=500;}if(alive[actor])p.score+=state.mode==='basic'?500:150;p.cash+=alive[actor]?300:0;const other=state.players[1-actor];if(alive[1-actor]){other.score+=state.mode==='basic'?500:150;other.cash+=300;}if(state.round>=state.maxRounds){state.winner=(state.mode==='greedy'?state.players[0].cash:state.players[0].score)===(state.mode==='greedy'?state.players[1].cash:state.players[1].score)?(state.players[0].hp>=state.players[1].hp?0:1):((state.mode==='greedy'?state.players[0].cash:state.players[0].score)>(state.mode==='greedy'?state.players[1].cash:state.players[1].score)?0:1);}else {state.round++;state.shots=0;state.ground=terrain((state.seed+state.round*7919)>>>0);state.wind=Math.round((((state.seed+state.round*17)%19)-9)*.8);for(const q of state.players){q.hp=100;q.yBefore=state.ground[q.x];}}}state.turn=1-actor;
state.last={actor,angle,power,weapon,hit,damages,ended};return state.last;}
export function bestShot(state,player){let best=null;for(let angle=20;angle<=80;angle+=2)for(let power=32;power<=100;power+=2){const t=trace(state,player,angle,power),enemy=state.players[1-player],distance=Math.hypot(enemy.x-t.x,state.ground[enemy.x]-t.y);if(!best||distance<best.distance)best={angle,power,distance};}return {angle:clamp(best.angle+Math.round((Math.random()-.5)*6),5,85),power:clamp(best.power+Math.round((Math.random()-.5)*6),10,100),weapon:'shell'};}
